CREATE TABLE public.artist_favorites(owner_id uuid NOT NULL,artist_id uuid NOT NULL REFERENCES public.artist_profiles(id),list text NOT NULL DEFAULT 'look' CHECK(list IN ('look','book')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,artist_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.artist_favorites TO authenticated; GRANT ALL ON public.artist_favorites TO service_role; ALTER TABLE public.artist_favorites ENABLE ROW LEVEL SECURITY; CREATE POLICY own_favorites ON public.artist_favorites FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE TABLE public.artist_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL UNIQUE REFERENCES public.bookings(id),patron_id uuid NOT NULL,artist_owner_id uuid NOT NULL,rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),body text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.artist_reviews TO authenticated;GRANT ALL ON public.artist_reviews TO service_role;ALTER TABLE public.artist_reviews ENABLE ROW LEVEL SECURITY;CREATE POLICY review_read ON public.artist_reviews FOR SELECT TO authenticated USING(patron_id=auth.uid() OR artist_owner_id=auth.uid() OR public.kalzo_is_admin());CREATE POLICY review_insert ON public.artist_reviews FOR INSERT TO authenticated WITH CHECK(patron_id=auth.uid() AND EXISTS(SELECT 1 FROM public.bookings b WHERE b.id=booking_id AND b.patron_id=auth.uid() AND b.artist_owner_id=artist_reviews.artist_owner_id AND b.workflow_stage='completed'));
CREATE TABLE public.artist_conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),patron_id uuid NOT NULL,artist_owner_id uuid NOT NULL,artist_id uuid NOT NULL REFERENCES public.artist_profiles(id),artist_name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(patron_id,artist_id));
GRANT SELECT,INSERT ON public.artist_conversations TO authenticated;GRANT ALL ON public.artist_conversations TO service_role;ALTER TABLE public.artist_conversations ENABLE ROW LEVEL SECURITY;CREATE POLICY conversation_read ON public.artist_conversations FOR SELECT TO authenticated USING(patron_id=auth.uid() OR artist_owner_id=auth.uid() OR public.kalzo_is_admin());
CREATE TABLE public.artist_chat_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES public.artist_conversations(id),sender_id uuid NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.artist_chat_messages TO authenticated;GRANT ALL ON public.artist_chat_messages TO service_role;ALTER TABLE public.artist_chat_messages ENABLE ROW LEVEL SECURITY;CREATE POLICY message_read ON public.artist_chat_messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.artist_conversations c WHERE c.id=conversation_id AND (c.patron_id=auth.uid() OR c.artist_owner_id=auth.uid() OR public.kalzo_is_admin())));CREATE POLICY message_insert ON public.artist_chat_messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND EXISTS(SELECT 1 FROM public.artist_conversations c WHERE c.id=conversation_id AND (c.patron_id=auth.uid() OR c.artist_owner_id=auth.uid())));
CREATE TABLE public.artist_meetings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES public.artist_conversations(id),requested_by uuid NOT NULL,event_at timestamptz NOT NULL,duration_minutes integer NOT NULL DEFAULT 30 CHECK(duration_minutes IN (15,30,45,60)),timezone text NOT NULL DEFAULT 'Asia/Kolkata',status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted_setup_required','accepted','declined','cancelled','completed')),recording_consent boolean NOT NULL DEFAULT false,zoom_id text,join_url text,recording_url text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.artist_meetings TO authenticated;GRANT ALL ON public.artist_meetings TO service_role;ALTER TABLE public.artist_meetings ENABLE ROW LEVEL SECURITY;CREATE POLICY meeting_read ON public.artist_meetings FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.artist_conversations c WHERE c.id=conversation_id AND (c.patron_id=auth.uid() OR c.artist_owner_id=auth.uid() OR public.kalzo_is_admin())));CREATE POLICY meeting_insert ON public.artist_meetings FOR INSERT TO authenticated WITH CHECK(requested_by=auth.uid() AND status='pending' AND zoom_id IS NULL AND join_url IS NULL AND recording_url IS NULL AND EXISTS(SELECT 1 FROM public.artist_conversations c WHERE c.id=conversation_id AND (c.patron_id=auth.uid() OR c.artist_owner_id=auth.uid())));
CREATE FUNCTION public.kalzo_open_artist_chat(p_artist uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.artist_profiles%ROWTYPE;cid uuid;BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required';END IF;SELECT * INTO a FROM public.artist_profiles WHERE id=p_artist AND status='approved' AND verification_status='verified';IF NOT FOUND OR a.owner_id=auth.uid() THEN RAISE EXCEPTION 'Choose an approved artist';END IF;INSERT INTO public.artist_conversations(patron_id,artist_owner_id,artist_id,artist_name) VALUES(auth.uid(),a.owner_id,a.id,a.stage_name) ON CONFLICT(patron_id,artist_id) DO UPDATE SET artist_name=EXCLUDED.artist_name RETURNING id INTO cid;RETURN cid;END $$;REVOKE ALL ON FUNCTION public.kalzo_open_artist_chat(uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.kalzo_open_artist_chat(uuid) TO authenticated;
CREATE FUNCTION public.kalzo_chat_notify() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.artist_conversations%ROWTYPE;BEGIN SELECT * INTO c FROM public.artist_conversations WHERE id=NEW.conversation_id;IF NEW.sender_id<>c.artist_owner_id THEN PERFORM public.kalzo_notify(c.artist_owner_id,'chat','New message from a patron',left(NEW.body,120),NULL);END IF;RETURN NEW;END $$;CREATE TRIGGER kalzo_chat_notify AFTER INSERT ON public.artist_chat_messages FOR EACH ROW EXECUTE FUNCTION public.kalzo_chat_notify();
CREATE FUNCTION public.kalzo_meeting_notify() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.artist_conversations%ROWTYPE;BEGIN SELECT * INTO c FROM public.artist_conversations WHERE id=NEW.conversation_id;PERFORM public.kalzo_notify(c.artist_owner_id,'meeting','Scheduled call invitation',to_char(NEW.event_at AT TIME ZONE 'Asia/Kolkata','DD Mon YYYY HH12:MI AM')||' IST — review in Chats & calls.',NULL);RETURN NEW;END $$;CREATE TRIGGER kalzo_meeting_notify AFTER INSERT ON public.artist_meetings FOR EACH ROW EXECUTE FUNCTION public.kalzo_meeting_notify();
CREATE FUNCTION public.kalzo_review_notification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.kalzo_notify(NEW.artist_owner_id,'rating','New performance review',NEW.rating||'/5 — '||left(NEW.body,120),NEW.booking_id);RETURN NEW;END $$;CREATE TRIGGER kalzo_review_notification AFTER INSERT ON public.artist_reviews FOR EACH ROW EXECUTE FUNCTION public.kalzo_review_notification();
CREATE FUNCTION public.kalzo_decide_meeting(p_meeting uuid,p_accept boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.artist_meetings m SET status=CASE WHEN p_accept THEN 'accepted_setup_required' ELSE 'declined' END WHERE m.id=p_meeting AND m.status='pending' AND EXISTS(SELECT 1 FROM public.artist_conversations c WHERE c.id=m.conversation_id AND c.artist_owner_id=auth.uid());IF NOT FOUND THEN RAISE EXCEPTION 'Only the invited artist can respond to this pending invitation';END IF;END $$;REVOKE ALL ON FUNCTION public.kalzo_decide_meeting(uuid,boolean) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.kalzo_decide_meeting(uuid,boolean) TO authenticated;